#!/usr/bin/env node
/**
 * Builds the two runtime files behind URL and URLSearchParams from the `whatwg-url` and `tr46` packages (both MIT,
 * devDependencies here): quickjs/runtime/whatwg-url.js, the URL Standard's parser and the WebIDL classes around it, and
 * quickjs/runtime/idna-data.js, the UTS #46 tables, which the first non-ASCII host name loads.
 *
 *   node tools/gen-whatwg-url.js
 *
 * The generated files are committed; regenerate them only to move to newer versions of the packages.
 */
const { build } = require("esbuild");
const { readFileSync, writeFileSync } = require("node:fs");
const { join, resolve } = require("node:path");

const root = resolve(__dirname, "..");
const out = join(root, "quickjs/runtime");
const version = (name) => JSON.parse(readFileSync(join(root, "node_modules", name, "package.json"), "utf-8")).version;

const swap = {
	name: "graak-shims",
	setup(b) {
		b.onResolve({ filter: /^tr46$/ }, () => ({ path: join(__dirname, "whatwg-url/tr46-shim.js") }));
		b.onResolve({ filter: /^\.\/encoding$/ }, (args) =>
			args.importer.includes("whatwg-url") ? { path: join(__dirname, "whatwg-url/encoding.js") } : undefined
		);
	},
};

async function main() {
	const header = (title, what) => `/*
 * ${title}: ${what}
 * Generated by tools/gen-whatwg-url.js from whatwg-url ${version("whatwg-url")}, tr46 ${version("tr46")} and webidl-conversions
 * ${version("webidl-conversions")} (all MIT, © their authors). Do not edit; regenerate.
 */
`;
	const main = await build({
		stdin: { contents: 'export { URL, URLSearchParams } from "whatwg-url";', resolveDir: root, sourcefile: "entry.js" },
		bundle: true,
		format: "esm",
		platform: "neutral",
		mainFields: ["main"],
		target: "es2020",
		write: false,
		plugins: [swap],
		legalComments: "none",
		minify: false,
		keepNames: true,
	});
	writeFileSync(
		join(out, "whatwg-url.js"),
		header("URL and URLSearchParams", "the WHATWG URL Standard (whatwg-url), bundled") + main.outputFiles[0].text
	);

	const idna = await build({
		stdin: { contents: 'globalThis.__graak_tr46 = require("tr46");', resolveDir: root, sourcefile: "entry.js" },
		bundle: true,
		format: "iife",
		platform: "neutral",
		mainFields: ["main"],
		target: "es2020",
		write: false,
		legalComments: "none",
		minify: true,
	});
	writeFileSync(
		join(out, "idna-data.js"),
		header("IDNA", "the UTS #46 processing and mapping tables (tr46), a script loaded on demand") +
			idna.outputFiles[0].text
	);
	console.log("wrote whatwg-url.js and idna-data.js");
}

main().catch((err) => {
	console.error(err);
	process.exit(1);
});
